import java.io.*;
import java.util.*;

public class Check3 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        long n = Long.parseLong(parts[0]);
        long m = Long.parseLong(parts[1]);
        long res = calculate(n, m);
        System.out.println(res);
    }

    static long calculate(long n, long m) {
        long a = Math.min(n, m);
        long b = Math.max(n, m);
        long total = n * m;

        if (a <= 3 && b <= 3) {
            if (a == 1 || b == 1) return 0;
            if (a == 2 && b == 2) return 0;
            if (a == 2 && b == 3) return 4;
            if (a == 3 && b == 2) return 4;
            if (a == 3 && b == 3) return 8;
            return 0;
        }

        if (a == 1) {
            long modVal = b % 6;
            if (modVal == 4) modVal = 2;
            else if (modVal == 5) modVal = 1;
            return total - modVal;
        } else if (a == 2) {
            if (b == 3 || b == 7) b = 2;
            else b = 0;
            return total - b;
        } else {
            return total - (total % 2);
        }
    }
}
